import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Roadmap","description":"Planned features, future enhancements, and the long-term vision for AzureScout.","frontmatter":{"description":"Planned features, future enhancements, and the long-term vision for AzureScout."},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),n={name:"roadmap.md"};function d(s,e,i,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p><em>See everything. Own your cloud.</em></p><p>This page outlines what&#39;s planned, what&#39;s in progress, and what&#39;s been delivered. Community contributions are welcome — see <a href="./contributing.html">Contributing</a> to get involved.</p><blockquote><p>The consolidated architecture, work-item index, audit findings, and delivery plan live in the <a href="./design/master-plan.html">Master Design &amp; Plan</a>. This roadmap is the public-facing summary of it.</p></blockquote><h2 id="current-release-—-v2-5-2-—-determinism" tabindex="-1">Current Release — v2.5.2 — Determinism <a class="header-anchor" href="#current-release-—-v2-5-2-—-determinism" aria-label="Permalink to &quot;Current Release — v2.5.2 — Determinism&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>A whole report category could silently vanish from a run. <code>Start-Job</code> is asynchronous, so a job created moments earlier sits in <code>NotStarted</code> — a state the wait loop and the batch filter both ignored, so it was never waited on, then harvested and destroyed before it produced anything. <code>Compute.json</code> came back 5,158 bytes on one run and 470 on the next against an unchanged tenant.</p><p>Both now treat every non-terminal state as pending, a dropped category emits a warning naming it instead of failing silently, and a machine without Excel installed gets a plain one-line explanation rather than a raw COM <code>0x80040154</code> error on a run that otherwise succeeded.</p><p>Verified by <strong>three consecutive live runs producing byte-identical results</strong>: 227 Azure resources, 994 Excel rows, 40 Power BI files / 1013 rows, 166 Azure DevOps resources, 0 empty-category warnings, 0 raw COM errors.</p><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#252---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.2</a>.</p><h2 id="previous-release-—-v2-5-1-—-live-run-hardening" tabindex="-1">Previous Release — v2.5.1 — Live-Run Hardening <a class="header-anchor" href="#previous-release-—-v2-5-1-—-live-run-hardening" aria-label="Permalink to &quot;Previous Release — v2.5.1 — Live-Run Hardening&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>Seven defects stopped a full <code>Invoke-AzureScout</code> run from completing against a real tenant. Extraction and processing succeeded, then the reporting layer threw <em>after</em> every worksheet had already been built. Fixed: an uninitialised extraction variable, 41 <code>.IsPresent</code> reads on parameters that are not declared <code>[switch]</code>, Excel styling and tables applied over empty worksheets, VM property names the Compute collector never emitted, 29 unguarded worksheet dereferences, 10 pivot titles read before assignment, and a Markdown string-interpolation bug.</p><p><strong>Every one was found by running the product end to end against live Azure.</strong> The 1692-test suite passed the whole time, because nothing exercised the extraction, processing and reporting chain against real collector output. This release also carries the first live-tenant verification of the <code>-IncludeDevOps</code> collectors — 166 resources across 74 projects — which previously had only mocked tests.</p><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#251---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.1</a>.</p><h2 id="previous-release-—-v2-5-0-—-one-collection-pass" tabindex="-1">Previous Release — v2.5.0 — One Collection Pass <a class="header-anchor" href="#previous-release-—-v2-5-0-—-one-collection-pass" aria-label="Permalink to &quot;Previous Release — v2.5.0 — One Collection Pass&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><p>A combined inventory + assessment run now queries Azure <strong>once</strong> (AB#5543). The inventory pass already projects the full property bag for every resource, so the assessment shapes its scores from those rows rather than re-issuing its own Resource Graph pack over the same resource types. One query still goes to Azure in a combined run — the Defender for SQL pricing lookup, which reads a table the inventory does not collect. The assessment-only path is unchanged.</p><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#250---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.5.0</a>.</p><h2 id="previous-release-—-v2-4-0-—-one-command-and-a-guided-wizard" tabindex="-1">Previous Release — v2.4.0 — One Command, and a Guided Wizard <a class="header-anchor" href="#previous-release-—-v2-4-0-—-one-command-and-a-guided-wizard" aria-label="Permalink to &quot;Previous Release — v2.4.0 — One Command, and a Guided Wizard&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>One entry point</td><td>Inventory and assessment are modes of a single <code>Invoke-AzureScout</code>, not two cmdlets. <code>-Assessment</code> selects the CAF/WAF assessment; <code>-CollectOnly</code> and <code>-FromCollect</code> moved across too. Assessment mode now honours the inventory sign-in parameters, which the standalone cmdlet never did (AB#5540)</td></tr><tr><td>Guided wizard</td><td>A bare <code>Invoke-AzureScout</code> in an interactive session signs you in, lets you pick the tenant, verifies your rights, then offers pre-selected checklists for run type, categories/assessments, formats, and report directory — and prints the equivalent one-liner. Never fires in CI; <code>-NoWizard</code> opts out (AB#5541)</td></tr><tr><td>Output formats</td><td><code>-OutputFormat</code> accepts several renderers in one run and spans both modes; a wrong-mode format now throws an error naming the switch you wanted</td></tr><tr><td>Deprecation</td><td><code>Invoke-ScoutAssessment</code> still works but will be removed in v3.0.0</td></tr><tr><td>Documentation</td><td>Corrected pages claiming a PowerShell 5.1 floor the module never had, and collapsed the &quot;Inventory vs Assessment&quot; framing across the site</td></tr></tbody></table><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#240---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.4.0</a>.</p><div class="tip custom-block"><p class="custom-block-title">Resolved in v2.5.0</p><p>The duplicate collection pass described here was collapsed in v2.5.0 (AB#5543) — a combined run now collects from Azure once.</p></div><h2 id="v2-3-0-—-collection-hardening-external-platform-integrations" tabindex="-1">v2.3.0 — Collection Hardening &amp; External Platform Integrations <a class="header-anchor" href="#v2-3-0-—-collection-hardening-external-platform-integrations" aria-label="Permalink to &quot;v2.3.0 — Collection Hardening &amp; External Platform Integrations&quot;">​</a></h2><p>Released 25 July 2026, published to the PowerShell Gallery. Closes the collection-hardening epic and the external-platform integrations.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Run isolation</td><td>Every invocation writes to its own run folder, so a rescan — or a scan of a second tenant — can no longer destroy the previous run&#39;s cache or report. <code>-RunName</code>, <code>-Force</code>, <code>Clear-AZSCCacheFolder -OlderThan &lt;days&gt;</code> (AB#331)</td></tr><tr><td>Azure DevOps inventory</td><td><code>-IncludeDevOps</code> adds projects, pipelines, service connections, repositories, and agent pools. The service-connection sheet cross-references each ARM connection against the subscriptions in scope (AB#327)</td></tr><tr><td>Unattended execution</td><td>Composite GitHub Action at the repository root (AB#328); the eight-step <a href="./automation.html">Azure Automation Account</a> guide plus two runbook upload fixes (AB#343)</td></tr><tr><td>Reliability</td><td>Subscription context restored in a <code>finally</code> at all five <code>Set-AzContext</code> sites (AB#368); post-login management group access probe naming the role to assign (AB#351)</td></tr><tr><td>Documentation</td><td><a href="./category-reference.html">Category Reference</a> (AB#318/5417) and <a href="./validation-matrix.html">Validation Matrix</a> (AB#315)</td></tr></tbody></table><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#230---2026-07-25" target="_blank" rel="noreferrer">CHANGELOG.md § 2.3.0</a>.</p><h2 id="v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" tabindex="-1">v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors <a class="header-anchor" href="#v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" aria-label="Permalink to &quot;v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors&quot;">​</a></h2><p>Four new report tiers, richer visuals on the existing ones, three new offline analysis functions, deeper collector coverage, and a round of platform hardening on top of v2.1.0.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Report tiers</td><td><code>Word</code> (<code>.docx</code> via OpenXML, AB#333), <code>EChartsDashboard</code> (offline ECharts HTML, AB#344), <code>Pdf</code> (dependency-free, AB#379/394/395), <code>JsonEvidence</code> (resources-only, AB#396) — all on <code>Export-Report</code> / <code>-OutputFormat</code></td></tr><tr><td>Reporting depth</td><td>Excel visual dashboard tabs with pivot charts (AB#322); richer React report — topology diagram, MG hierarchy, 14 KPI cards, Governance section, drill-downs, search/filter, badges, tooltips (AB#376–378, 380, 386, 387, 389–393); <code>report.pbit</code> generation (AB#5046)</td></tr><tr><td>New analysis</td><td><code>Get-ScoutInventoryDrift</code> (cross-run resource drift, AB#326), <code>Get-ScoutCostAnomaly</code> (cost outliers, AB#324), <code>Get-ScoutIacGap</code> (Bicep/IaC coverage gaps, AB#325) — all offline, never call Azure</td></tr><tr><td>Collect layer</td><td>IoT deep coverage — DPS + Digital Twins (AB#330); tag-value aggregation (AB#367); deeper Database/Analytics/IoT rule automation (AB#5068/5071/5075); per-subscription collector/pipeline resilience + live progress (AB#397–402, 405)</td></tr><tr><td>Config</td><td><code>Import-ScoutConfig</code> / <code>Export-ScoutConfig</code> (AB#373–375) — save/reload a benchmark + rule-selection + threshold-override config as JSON, with a safe fallback to the built-in default</td></tr><tr><td>Platform</td><td>CI pipeline (AB#317); a real, non-simulated <code>azure-inventory</code> workflow (AB#340); module auto-update check (AB#369); login auth banner (AB#349); five v1 inventory bug fixes (AB#335–340); draw.io merge/StrictMode repairs (AB#342); documented Entra Graph delegated scopes (AB#347/338)</td></tr></tbody></table><p>Full detail: <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#220---2026-07-24" target="_blank" rel="noreferrer">CHANGELOG.md § 2.2.0</a>.</p><h2 id="v2-1-0-—-platform-hardening" tabindex="-1">v2.1.0 — Platform Hardening <a class="header-anchor" href="#v2-1-0-—-platform-hardening" aria-label="Permalink to &quot;v2.1.0 — Platform Hardening&quot;">​</a></h2><p>Released 23 July 2026. Native governance collector (AB#5041), unattended one-command pipeline (AB#5050), and the React report variant + cross-run drift tracking (AB#5053). See the <a href="#major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23">v2.1.0 section</a> below for the full breakdown.</p><h2 id="v2-0-0-—-caf-waf-assessment-platform" tabindex="-1">v2.0.0 — CAF/WAF Assessment Platform <a class="header-anchor" href="#v2-0-0-—-caf-waf-assessment-platform" aria-label="Permalink to &quot;v2.0.0 — CAF/WAF Assessment Platform&quot;">​</a></h2><p>Released 23 July 2026. Turns AzureScout from an inventory tool into a read-only CAF/WAF landing-zone assessment. Runtime-verified offline (Pester) and against a live Azure tenant.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What shipped</th></tr></thead><tbody><tr><td>Assessment engine</td><td>Declarative YAML rules (JSONPath + assert types), dual CAF/WAF scoring, prioritized gap list — <strong>139 rules across 8 CAF design areas + 5 WAF pillars</strong></td></tr><tr><td>Collect + ingest</td><td>Read-only ARG collect layer (<code>collect.json</code>); native governance collector (v2.1.0) / ARG query pack / Advisor ingest — AzGovViz retained as opt-in only</td></tr><tr><td>ALZ benchmark</td><td>Live tenant diffed against a canonical ALZ reference</td></tr><tr><td>Tiered reporting</td><td>Power BI, self-contained HTML, executive <strong>PowerPoint (OpenXML SDK — no Python)</strong>, Excel + JSON evidence</td></tr><tr><td>Per-domain analytics</td><td>Every discovery category runnable + tagged: <code>Invoke-AzureScout -Assessment &lt;Category&gt;</code></td></tr><tr><td>Entry point</td><td><code>Invoke-AzureScout -Assessment</code> (run one/some/all), read-only permission pre-flight</td></tr></tbody></table><blockquote><p><strong>Breaking:</strong> introduces the <code>findings.json</code> contract and demotes Excel-first output to an evidence tier. Assessment features require PowerShell 7.</p></blockquote><p>Deferred to v2.1.0: full per-category rule depth (AB#5061–5075). The native governance collector (AB#5041), the fully unattended pipeline (AB#5050), and the React report variant + cross-run drift tracking (AB#5053) shipped in v2.1.0; four new report tiers, deeper analysis functions, and collector hardening shipped in v2.2.0 above.</p><h2 id="previous-release-—-v1-0-0" tabindex="-1">Previous Release — v1.0.0 <a class="header-anchor" href="#previous-release-—-v1-0-0" aria-label="Permalink to &quot;Previous Release — v1.0.0&quot;">​</a></h2><p>Released February 2026.</p><table tabindex="0"><thead><tr><th>Area</th><th>What&#39;s included</th></tr></thead><tbody><tr><td>Excel Reports</td><td>171 worksheets (154 ARM + 17 Entra ID) covering all 15 Azure resource categories</td></tr><tr><td>Category Filtering</td><td><code>-Category</code> parameter to scope runs to specific resource types</td></tr><tr><td>AI / ML Coverage</td><td>27 modules: OpenAI, AI Foundry, Azure ML, Cognitive Services, Bot Services, Search</td></tr><tr><td>AVD Coverage</td><td>6 modules: Host Pools, App Groups, Workspaces, Session Hosts, Scaling Plans, Applications</td></tr><tr><td>Arc Coverage</td><td>Sites, SQL Servers, Data Controllers, SQL Managed Instances, Arc-enabled Kubernetes enhancements</td></tr><tr><td>VM &amp; Arc Enrichment</td><td>Backup status, Site Recovery, Update Manager, Advisor score, Monitor metrics, Cost estimates</td></tr><tr><td>Monitor Coverage</td><td>24 modules: Diagnostic settings, alert rules, DCRs, App Insights deep data, autoscale, workbooks</td></tr><tr><td>Markdown / AsciiDoc Export</td><td><code>-OutputFormat Markdown|AsciiDoc</code> generates portable reports alongside Excel/JSON</td></tr><tr><td>Permission Audit</td><td><code>Invoke-AZSCPermissionAudit</code> with ARM + Graph checks, color output, Markdown/AsciiDoc export</td></tr><tr><td>Subscription &amp; MG Completeness</td><td>Captures ALL subscriptions (including empty/disabled) and full MG hierarchy</td></tr><tr><td>Module Naming</td><td>Renamed from <em>AzureTenantInventory</em> to <em>AzureScout</em> (prefix: <code>AZSC</code>)</td></tr></tbody></table><h2 id="near-term-—-v1-1-0" tabindex="-1">Near-term — v1.1.0 <a class="header-anchor" href="#near-term-—-v1-1-0" aria-label="Permalink to &quot;Near-term — v1.1.0&quot;">​</a></h2><p>Focus: quality, reliability, and community onboarding.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Pester test suite</td><td>Full unit + integration tests for all public functions and key private functions</td><td>✅ Done — 1,648 tests across 56 files, run offline</td></tr><tr><td>PSGallery publish</td><td>Publish <code>AzureScout</code> module to PowerShell Gallery</td><td>✅ Done (v2.0.0)</td></tr><tr><td>GitHub Actions CI</td><td>Run Pester tests on PR + push; block merge on failure</td><td>✅ Done — <code>ci.yml</code> runs Pester + PSScriptAnalyzer on every push and PR</td></tr><tr><td>Category alias documentation</td><td>Comprehensive table of all accepted <code>-Category</code> aliases and their canonical names</td><td>✅ Done (v2.3.0, AB#318/AB#5417) — see <a href="./category-reference.html">Category Reference</a></td></tr><tr><td>Resource provider pre-flight</td><td>Warn before scan when required providers are not registered in a subscription</td><td>✅ Done — <code>-CheckResourceProviders</code></td></tr><tr><td>Throttling / retry improvements</td><td>Exponential backoff on 429 responses, honouring <code>Retry-After</code>, plus 5xx retry</td><td>✅ Done — <code>Invoke-AZSCGraphRequest</code> (<code>-MaxRetries</code>, default 5)</td></tr><tr><td><code>Invoke-AzureScout -WhatIf</code></td><td>Show which modules would run without actually executing</td><td>❌ Won&#39;t do (AB#321) — Azure Scout is read-only, so <code>-WhatIf</code> has no state change to preview</td></tr><tr><td>Non-destructive cache</td><td>Prevent <code>ReportCache</code> and <code>DiagramCache</code> from being overwritten on subsequent runs. Each invocation writes to a timestamped (or <code>-RunName</code> named) subfolder. Previous scan data is never lost unless <code>-Force</code> is specified. <code>Clear-AZSCCacheFolder -OlderThan &lt;days&gt;</code> for cleanup.</td><td>✅ Done (v2.3.0, AB#331)</td></tr><tr><td>Cross-subscription context restore</td><td>Restore the caller&#39;s subscription context after every per-subscription loop, including on error</td><td>✅ Done (v2.3.0, AB#368)</td></tr><tr><td>Management group access probe</td><td>Report management group visibility at login and name the role to assign when it is missing</td><td>✅ Done (v2.3.0, AB#351)</td></tr></tbody></table><h3 id="visual-dashboard-tabs-darkblue-overview-style-worksheets" tabindex="-1">Visual Dashboard Tabs (DarkBlue &quot;overview-style&quot; worksheets) <a class="header-anchor" href="#visual-dashboard-tabs-darkblue-overview-style-worksheets" aria-label="Permalink to &quot;Visual Dashboard Tabs (DarkBlue &quot;overview-style&quot; worksheets)&quot;">​</a></h3><p>Phase 10 added raw data tabs (Cost Management, Security Overview, Azure Update Manager, Azure Monitor) that collect data into flat tables. The next step is to add <strong>visual dashboard tabs</strong> — styled like the Overview sheet (DarkBlue tab color, EPPlus shapes, pivot charts) — that summarize and visualize the data from those raw tabs.</p><table tabindex="0"><thead><tr><th>Dashboard</th><th>Charts / Visualizations</th><th>Status</th></tr></thead><tbody><tr><td>Cost Dashboard</td><td>Cost by Resource Type (bar), Cost by Subscription (pie), Cost by Region (column), Cost by SKU (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Security Dashboard</td><td>Assessments by Severity (pie), Findings by Subscription (bar), Defender Plans (column), Active Alerts by Severity (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Update Manager Dashboard</td><td>Machines by Platform (pie), Machines by OS Type (pie), Machines by Region (column), Machines by Power State (bar), Machines by Subscription (bar)</td><td>:blue_circle: Planned</td></tr><tr><td>Monitor Dashboard</td><td>Alert Rules by Subscription (bar), Action Groups by Subscription (pie), DCRs by Subscription (column), App Insights by Subscription (bar)</td><td>:blue_circle: Planned</td></tr></tbody></table><p>Each dashboard tab will:</p><ul><li>Use DarkBlue tab color (matching Overview, Subscriptions, Advisor)</li><li>Be pinned after the Overview sheet group via <code>MoveAfter</code> in the ordering function</li><li>Contain EPPlus pivot tables + charts generated by <code>Build-AZSCDashboardTabs</code></li><li>Only appear when the corresponding raw data tab has data (no empty dashboards)</li></ul><h2 id="medium-term-—-v1-2-0" tabindex="-1">Medium-term — v1.2.0 <a class="header-anchor" href="#medium-term-—-v1-2-0" aria-label="Permalink to &quot;Medium-term — v1.2.0&quot;">​</a></h2><p>Focus: depth, breadth, and multi-tenant scenarios.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Multi-tenant scanning (Lighthouse)</td><td><code>-TenantID</code> accepts multiple tenant IDs. Authenticates to each tenant sequentially, runs the full extraction → processing → reporting pipeline per tenant. Supports combined workbook (with Tenant column) or separate per-tenant workbooks via <code>-MergeOutput</code> switch. Auth failure on one tenant does not block others. The run-isolation prerequisite shipped in v2.3.0 (AB#331).</td><td>💡 Idea (AB#323)</td></tr><tr><td>Word document export (#22)</td><td>Shipped as <code>-OutputFormat Word</code> on <code>Invoke-ScoutAssessment</code> (v2.2.0): <code>Export-Word</code> generates a self-contained <code>.docx</code> via OpenXML, no Python.</td><td>✅ Done (v2.2.0, AB#333)</td></tr><tr><td>PDF report export (#23)</td><td>Shipped as <code>-OutputFormat Pdf</code> on <code>Invoke-ScoutAssessment</code> (v2.2.0): <code>Export-Pdf</code> is a hand-rolled, dependency-free renderer (cover, executive summary, per-area findings table, gaps, manual review).</td><td>✅ Done (v2.2.0, AB#379/394/395)</td></tr><tr><td>Cost anomaly detection</td><td>Shipped as the offline <code>Get-ScoutCostAnomaly</code> function (v2.2.0) — flags statistical outliers (spike/z-score/IQR) in an already-collected cost dataset; never calls Azure.</td><td>✅ Done (v2.2.0, AB#324)</td></tr><tr><td>Bicep / IaC gap detection</td><td>Shipped as the offline <code>Get-ScoutIacGap</code> function (v2.2.0) — compares discovered resources against a folder of Bicep/ARM-JSON templates and flags unmanaged resources; never calls Azure.</td><td>✅ Done (v2.2.0, AB#325)</td></tr><tr><td>Resource drift reporting</td><td>Shipped as the offline <code>Get-ScoutInventoryDrift</code> function (v2.2.0) — compares the current <code>collect.json</code> against the previous run&#39;s snapshot and reports Added/Removed/Changed resources.</td><td>✅ Done (v2.2.0, AB#326)</td></tr><tr><td>Azure DevOps integration</td><td>Shipped as <code>-IncludeDevOps</code> (v2.3.0) — inventories projects, pipelines, service connections, repositories, and agent pools across one or more organizations, adding five worksheets. Authentication reuses the current Azure sign-in; <code>-DevOpsPat</code> covers a separate identity. The ADO Service Connections sheet cross-references each ARM connection against the subscriptions in scope.</td><td>✅ Done (v2.3.0, AB#327)</td></tr><tr><td>GitHub Actions module</td><td>Shipped as a composite <code>action.yml</code> at the repository root (v2.3.0) — <code>uses: thisismydemo/azure-scout@v2</code> installs the module, authenticates, collects, and uploads reports as an artifact.</td><td>✅ Done (v2.3.0, AB#328)</td></tr><tr><td>Azure Automation Account</td><td>Shipped as first-class unattended execution (v2.3.0) — the eight-step setup guide now exists, plus fixes for the blob-upload collision on a second scheduled run and the diagnostic log that never uploaded.</td><td>✅ Done (v2.3.0, AB#343)</td></tr><tr><td>Fabric / Power BI export (#17)</td><td><code>-OutputFormat PowerBI</code> generates a flat normalized CSV bundle (<code>PowerBI/</code> folder) with <code>_metadata.csv</code>, <code>Subscriptions.csv</code>, per-module <code>Resources_*.csv</code> and <code>Entra_*.csv</code> files, and a <code>_relationships.json</code> star-schema manifest for Power BI Desktop / Microsoft Fabric</td><td>✅ Done</td></tr><tr><td>IoT deep coverage</td><td>Shipped in the assessment Collect layer (v2.2.0) — <code>Invoke-Collect</code> gains Device Provisioning Service and Azure Digital Twins queries; new <code>caf.iot</code> rules score them.</td><td>✅ Done (v2.2.0, AB#330)</td></tr></tbody></table><h2 id="major-—-v2-0-0-—-caf-waf-assessment-platform-epic-ab-5023-—-delivered" tabindex="-1">Major — v2.0.0 — CAF/WAF Assessment Platform (Epic AB#5023) — Delivered <a class="header-anchor" href="#major-—-v2-0-0-—-caf-waf-assessment-platform-epic-ab-5023-—-delivered" aria-label="Permalink to &quot;Major — v2.0.0 — CAF/WAF Assessment Platform (Epic AB#5023) — Delivered&quot;">​</a></h2><p>Turned inventory into a <strong>scored CAF/WAF landing-zone assessment</strong>. Collection stays as-is; a three-layer, JSON-on-disk architecture (<code>collect.json</code> → <code>findings.json</code> → deliverables) adds assessment and rebuilds reporting. Read-only throughout. <strong>Shipped in v2.0.0 (2026-07-23).</strong></p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Assessment engine</td><td>Declarative YAML rules (JSONPath + assert types), dual CAF/WAF scoring, prioritized gap list</td><td>✅ Done (AB#5027, AB#5034)</td></tr><tr><td>CAF/WAF rule content</td><td>8 CAF design areas + 5 WAF pillars — 139 rules across 23 version-controlled files</td><td>✅ Done (AB#5031, AB#5057)</td></tr><tr><td>Ingest layer</td><td>Fold an ARG query pack and Advisor into one <code>collect.json</code>; governance now ingested natively by default (see v2.1.0 below) — Azure Governance Visualizer remains available as an opt-in ingestor</td><td>✅ Done (AB#5037)</td></tr><tr><td>ALZ benchmark diff</td><td>Compare the live tenant against a canonical ALZ reference (MG archetypes, required policies)</td><td>✅ Done — engine + native governance collection, no upstream AzGovViz dependency (AB#5041, v2.1.0)</td></tr><tr><td>Tiered reporting</td><td>Power BI (primary), self-contained HTML, executive PPTX (OpenXML SDK); Excel/JSON retained as evidence</td><td>✅ Done (AB#5044)</td></tr><tr><td>Module registry + entry point</td><td><code>-Assessment</code> run one/some/all; read-only permission pre-flight</td><td>✅ Done (AB#5024); unattended one-command pipeline ✅ Done (AB#5050, v2.1.0)</td></tr><tr><td>React report + drift tracking</td><td>Richer React report variant and cross-run score-drift tracking</td><td>✅ Done (AB#5053, v2.1.0)</td></tr></tbody></table><h2 id="major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23" tabindex="-1">Major — v2.1.0 — Platform Hardening (Epic AB#5023 carryover) — Released 2026-07-23 <a class="header-anchor" href="#major-—-v2-1-0-—-platform-hardening-epic-ab-5023-carryover-—-released-2026-07-23" aria-label="Permalink to &quot;Major — v2.1.0 — Platform Hardening (Epic AB#5023 carryover) — Released 2026-07-23&quot;">​</a></h2><p>Three more Epic AB#5023 capabilities shipped ahead of the full per-domain analytics epic below. Tagged and released as <code>v2.1.0</code> — see <a href="https://github.com/thisismydemo/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for the build ledger.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Native governance collector</td><td><code>Import-Governance</code> replaces the AzGovViz hard dependency as the <strong>default</strong> governance collector — populates <code>collect.json</code>&#39;s <code>governance</code> object natively from Azure Resource Graph and ambient-token ARM REST, needing only Reader at the management-group root. No cloned repo, no <code>AzAPICall</code> install prompt, fully unattended, StrictMode-safe. Live-verified against the HCS tenant. <code>AzGovViz</code> remains available as an opt-in <code>Ingest</code> value; nothing depends on it by default anymore.</td><td>✅ Done (AB#5041)</td></tr><tr><td>Unattended pipeline</td><td><code>Invoke-ScoutPipeline</code> runs collect → assess → report headless into one dated run folder — non-interactive throughout, runs the read-only permission pre-flight first, and degrades to <code>PartialSuccess</code> (rather than losing output) if an exporter fails. Writes <code>pipeline-summary.json</code>/<code>.md</code>.</td><td>✅ Done (AB#5050)</td></tr><tr><td>React report + cross-run drift</td><td><code>-OutputFormat React</code> renders a single self-contained <code>report-react.html</code> (client-side filter/sort/search, summary dashboard, Drift tab). <code>Get-ScoutDrift</code> computes cross-run New / Resolved / Regressed / Unchanged findings plus a weighted score delta, tracked in an append-only <code>.scout-history/findings-history.json</code>.</td><td>✅ Done (AB#5053)</td></tr></tbody></table><p>Not included in v2.1.0: full per-category rule depth (AB#5061–5075) — tracked below. Four new report tiers, richer report visuals, and three new offline analysis functions shipped in v2.2.0 next.</p><h2 id="major-—-v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" tabindex="-1">Major — v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors <a class="header-anchor" href="#major-—-v2-2-0-—-report-tiers-deeper-analytics-hardened-collectors" aria-label="Permalink to &quot;Major — v2.2.0 — Report Tiers, Deeper Analytics, Hardened Collectors&quot;">​</a></h2><p>Delivered on <code>main</code> — not yet tagged/published, see <a href="https://github.com/thisismydemo/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for cut status.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Report tiers — Word/ECharts/PDF/JSON evidence</td><td><code>Export-Word</code> (<code>.docx</code> via OpenXML), <code>Export-EChartsDashboard</code> (offline ECharts HTML, no CDN), <code>Export-Pdf</code> (hand-rolled, dependency-free), <code>Export-JsonEvidence</code> (resources-only JSON, no assessment metadata/scores). All wired into <code>Export-Report</code> and <code>-OutputFormat</code> on <code>Invoke-ScoutAssessment</code>/<code>Invoke-ScoutPipeline</code>.</td><td>✅ Done (AB#333, AB#344, AB#396, AB#379/394/395)</td></tr><tr><td>Excel visual dashboard tabs</td><td>Native ImportExcel PivotTable/PivotChart dashboard sheets in the assessment Excel evidence tier: Findings-by-Severity (pie), Score-by-Area (column), Pass-Fail-Manual (stacked column), Resource-Counts (bar) — omitted when a sheet&#39;s data is empty.</td><td>✅ Done (AB#322)</td></tr><tr><td>Richer React report + <code>report.pbit</code></td><td>The self-contained <code>report-react.html</code> gains a vis.js VNet topology diagram, an MG-hierarchy diagram, 14 KPI cards, an Azure Firewall drill-down, a Governance section (budgets/locks/tag chips), a policy-enforcement badge, per-section search/filter, clickable rows with a side panel, and scope tooltips. The Power BI tier also generates a <code>report.pbit</code> bound to the star-schema CSVs.</td><td>✅ Done (AB#376–378, 380, 386, 387, 389–393, AB#5046)</td></tr><tr><td>Cross-run resource drift</td><td><code>Get-ScoutInventoryDrift</code> — offline, compares the current <code>collect.json</code> against the previous run and reports Added/Removed/Changed resources, complementing the existing findings-level <code>Get-ScoutDrift</code> (v2.1.0).</td><td>✅ Done (AB#326)</td></tr><tr><td>Cost anomaly detection</td><td><code>Get-ScoutCostAnomaly</code> — offline, flags statistical outliers (month-over-month spike, z-score, IQR) in an already-collected cost dataset.</td><td>✅ Done (AB#324)</td></tr><tr><td>Bicep / IaC gap detection</td><td><code>Get-ScoutIacGap</code> — offline, compares discovered resources against a folder of Bicep/ARM-JSON templates (best-effort text/JSON parsing) and flags resources not represented in any template.</td><td>✅ Done (AB#325)</td></tr><tr><td>IoT deep coverage</td><td><code>Invoke-Collect</code> gains Device Provisioning Service and Azure Digital Twins queries; new <code>caf.iot</code> rules score them.</td><td>✅ Done (AB#330)</td></tr><tr><td>Tag aggregation</td><td><code>Invoke-Collect</code> aggregates tag values to their unique set per key across subscriptions instead of last-write-wins.</td><td>✅ Done (AB#367)</td></tr><tr><td>Database/Analytics/IoT rule depth</td><td>New <code>sqlDefenderPricing</code>/<code>purviewAccounts</code> collect queries plus <code>iotHubs.disableLocalAuth</code>; CAF-DB-04, CAF-ANL-02, and new CAF-IOT-06 flip from <code>Manual</code> to automated.</td><td>✅ Done (AB#5068, AB#5071, AB#5075)</td></tr><tr><td>Collector/pipeline resilience + progress</td><td>Per-subscription try/catch/continue in <code>Invoke-Collect</code>; a management-group role-requirement hint on RP/authorization errors; an empty-data guard; a pipeline <code>HadErrors</code> summary flag; live <code>Write-ScoutProgress</code> output during collection.</td><td>✅ Done (AB#397–402, AB#405)</td></tr><tr><td>Assessment config load/save</td><td><code>Import-ScoutConfig</code> / <code>Export-ScoutConfig</code> — load/save an alternative benchmark, rule-selection patterns, and per-rule threshold overrides as JSON; never throws on a bad file (falls back to the built-in default with a warning).</td><td>✅ Done (AB#373–375)</td></tr><tr><td>Platform hardening</td><td>CI pipeline (<code>ci.yml</code>); a real, non-simulated <code>azure-inventory</code> workflow; module auto-update check on import; UPN/subscription auth banner; five v1 inventory bug fixes; draw.io merge/StrictMode repairs; documented Entra Graph delegated scopes.</td><td>✅ Done (AB#317, AB#340, AB#369, AB#349, AB#335–340, AB#342, AB#347/338)</td></tr></tbody></table><p>Not yet included: full per-category rule depth (AB#5061–5075) — tracked below under Epic AB#5056.</p><h2 id="major-—-v2-1-0-—-per-domain-caf-waf-analytics-epic-ab-5056" tabindex="-1">Major — v2.1.0 — Per-Domain CAF/WAF Analytics (Epic AB#5056) <a class="header-anchor" href="#major-—-v2-1-0-—-per-domain-caf-waf-analytics-epic-ab-5056" aria-label="Permalink to &quot;Major — v2.1.0 — Per-Domain CAF/WAF Analytics (Epic AB#5056)&quot;">​</a></h2><p>Focus: extend CAF/WAF analytics to <strong>every</strong> Scout category, not just the landing-zone roll-up. Each of the 15 discovery categories becomes an <strong>independently runnable, categorized and tagged assessment</strong> — so you can run and score <em>just</em> Governance, <em>just</em> Monitoring, <em>just</em> Update Manager, etc.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Assessment taxonomy &amp; tagging</td><td>Manifest gains <code>Category</code> / <code>Frameworks</code> / <code>Tags</code>; <code>-Assessment &lt;Category&gt;</code> runs scoped discovery + scoped scoring; sub-bundles (Governance/Policy/UpdateManager under Management, Monitoring under Monitor)</td><td>:blue_circle: Planned (AB#5057)</td></tr><tr><td>Per-category coverage</td><td>CAF/WAF rule coverage authored for each category — Management, Monitor, Networking, Identity, Security, Compute, Storage, Databases, Containers, Web, Analytics, AI, Integration, Hybrid, IoT</td><td>:blue_circle: Planned (AB#5061–AB#5075)</td></tr><tr><td>Registry document</td><td>A table of every possible assessment: category, sub-bundles, CAF areas, WAF pillars, tags</td><td>:blue_circle: Planned (AB#5057)</td></tr></tbody></table><p>See <a href="https://github.com/thisismydemo/azure-scout/blob/main/RELEASES.md" target="_blank" rel="noreferrer"><code>RELEASES.md</code></a> for the build/release ledger.</p><h2 id="far-future-—-web-version-of-azure-scout-epic-ab-5093" tabindex="-1">Far-future — Web version of Azure Scout (Epic AB#5093) <a class="header-anchor" href="#far-future-—-web-version-of-azure-scout-epic-ab-5093" aria-label="Permalink to &quot;Far-future — Web version of Azure Scout (Epic AB#5093)&quot;">​</a></h2><blockquote><p>A <strong>web-UI version with the same capabilities as the PowerShell version</strong> — same engine, browser instead of terminal. <strong>Far-future, not scheduled.</strong> Only the web-only plumbing (server, runspace, progress polling, launchers) is unique to it. The actual product features are <strong>buildable in the PowerShell version now</strong> (Epic AB#5094) and the web version inherits them.</p></blockquote><blockquote><p><strong>Status: under evaluation — NOT committed.</strong> This is a possible future direction, not planned work, and it would be a <strong>departure from the current &quot;no portals&quot; stance</strong> in the <a href="#long-term-vision">Long-term Vision</a> below. Captured here so the direction is tracked and can be decided deliberately rather than drifting into the backlog.</p></blockquote><p>A <strong>served web-application</strong> as a <strong>second delivery surface</strong> for the same engine — not a different product. It would run a local HTTP listener with a browser UI (background-runspace collection with live progress, interactive vis.js topology, in-browser PDF export, config upload/download). <strong>The web portal must reach FEATURE PARITY with the PowerShell version</strong> — every product feature is available through both surfaces; neither has a feature the other lacks. Only the <em>delivery plumbing</em> below is web-specific. It is weeks of net-new engineering (web server + JS front-end + IPC layer).</p><p><strong>Web delivery surface — plumbing only (Epic AB#5093, exploratory):</strong></p><table tabindex="0"><thead><tr><th>Area</th><th>Web-surface plumbing (no PowerShell equivalent)</th><th>Status</th></tr></thead><tbody><tr><td>Server core</td><td>HTTP listener + background runspace, file-based progress IPC (client polls), named stages %, concurrent-collection guard, cached-inventory serving, runspace disposal, double-poll guard</td><td>💡 Exploratory (AB#381–385, 403, 404)</td></tr><tr><td>Launchers</td><td><code>start.cmd</code> / <code>start.sh</code> to launch the server</td><td>💡 Exploratory (AB#388)</td></tr></tbody></table><h3 id="feature-parity-—-shared-across-both-surfaces-epic-ab-5094" tabindex="-1">Feature parity — shared across both surfaces (Epic AB#5094) <a class="header-anchor" href="#feature-parity-—-shared-across-both-surfaces-epic-ab-5094" aria-label="Permalink to &quot;Feature parity — shared across both surfaces (Epic AB#5094)&quot;">​</a></h3><p>The product <strong>features</strong> below are <strong>not web-only or PowerShell-only — they belong to both surfaces</strong>. They live in the core product and are surfaced through the PowerShell module (CLI + static/React reports) <em>and</em> the web portal. Same capability, per-surface delivery:</p><ul><li><strong>Report visuals</strong> (in the React/HTML report today, and the web portal later): vis.js VNet topology + click-to-details + reset/fit controls, MG-hierarchy diagram, per-section search/filter, clickable rows + side panel, 14 KPI cards, Azure Firewall drill-down, Governance section (budgets/locks/tag chips), policy-enforcement badge, scope tooltips, resources-only JSON evidence export (AB#376–378, 380, 386, 387, 389–393, 396). <em>Several partially exist in the React report already — extend them.</em></li><li><strong>WAF config load/save + report PDF export</strong> (PowerShell via parameters/file output; web via browser upload/download + in-browser render) (AB#373–375, 379, 394, 395).</li><li><strong>Collector / pipeline resilience</strong> (shared engine): per-subscription try/catch/continue, MG role-requirement hint, false RP-registration-error swallow, per-group firewall-parse-error logging, empty-data guard, pipeline-<code>HadErrors</code> warning capture (AB#397–402).</li><li><strong>Live-progress UX</strong> — same feature, per-surface delivery: Spectre.Console TUI in the CLI, browser progress in the web portal (AB#405).</li></ul><h2 id="long-term-vision" tabindex="-1">Long-term Vision <a class="header-anchor" href="#long-term-vision" aria-label="Permalink to &quot;Long-term Vision&quot;">​</a></h2><p>AzureScout aims to be the definitive open-source Azure visibility tool for:</p><ul><li><strong>Architects</strong> — understand the full shape of a tenant before designing changes</li><li><strong>Security teams</strong> — identify misconfigured, unmonitored, or over-privileged resources</li><li><strong>FinOps practitioners</strong> — surface cost waste, reservation opportunities, and untagged resources</li><li><strong>Managed service providers</strong> — generate client-ready reports across multiple tenants</li></ul><p>The tool will remain <strong>open-source, PowerShell-native, and Excel-friendly</strong> — no agents, no portals, no licensing fees.</p><h2 id="completed-phases" tabindex="-1">Completed Phases <a class="header-anchor" href="#completed-phases" aria-label="Permalink to &quot;Completed Phases&quot;">​</a></h2><p>All implementation phases from the original migration plan are complete. See the <a href="./changelog.html">Changelog</a> for the full history.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Summary</th></tr></thead><tbody><tr><td>Phase 1-9</td><td>Core engine, module loading, Excel generation, JSON output, Draw.io diagrams, auth methods, connection handling, permission pre-flight</td></tr><tr><td>Phase 10</td><td>Specialized Excel tabs: Cost Management, Security Overview, Azure Update Manager, Azure Monitor</td></tr><tr><td>Phase 11</td><td>All-subscriptions + full MG hierarchy enumeration</td></tr><tr><td>Phase 12</td><td>ARM-only default scope, permission documentation, README overhaul</td></tr><tr><td>Phase 13</td><td>15 new Azure Monitor/Insights modules</td></tr><tr><td>Phase 14</td><td>15 new AI/ML modules</td></tr><tr><td>Phase 15</td><td>6 AVD modules + AVD on Azure Local/Arc detection</td></tr><tr><td>Phase 16</td><td>Arc site configs, Arc SQL Server, Arc Data Services enhancements</td></tr><tr><td>Phase 17</td><td>VM + Arc deep enrichment (metrics, backup, DR, cost, advisor)</td></tr><tr><td>Phase 18</td><td>Category folder alignment + <code>.CATEGORY</code> metadata parsing</td></tr><tr><td>Phase 19</td><td>Richer progress indicators, clear permission error messages</td></tr><tr><td>Phase 20</td><td><code>Invoke-AZSCPermissionAudit</code> + <code>Test-AZSCPermissions</code> refactor</td></tr><tr><td>Phase 21</td><td>Markdown + AsciiDoc export, <code>Export-AZSCMarkdownReport</code>, <code>Export-AZSCAsciiDocReport</code></td></tr></tbody></table><h2 id="suggest-a-feature" tabindex="-1">Suggest a Feature <a class="header-anchor" href="#suggest-a-feature" aria-label="Permalink to &quot;Suggest a Feature&quot;">​</a></h2><p>Open an issue at <a href="https://github.com/thisismydemo/azure-scout/issues" target="_blank" rel="noreferrer">github.com/thisismydemo/azure-scout/issues</a> with the label <code>enhancement</code>.</p><p>Pull requests are welcome — see <a href="./contributing.html">Contributing</a> for guidelines.</p><h2 id="fork-attribution" tabindex="-1">Fork Attribution <a class="header-anchor" href="#fork-attribution" aria-label="Permalink to &quot;Fork Attribution&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Fork Attribution</p><p><strong>AzureScout is a fork of <a href="https://github.com/microsoft/ARI" target="_blank" rel="noreferrer">Azure Resource Inventory (ARI)</a></strong> by Microsoft, originally created by <a href="https://github.com/Claudio-Merola" target="_blank" rel="noreferrer">Claudio Merola</a> and <a href="https://github.com/RenatoGregio" target="_blank" rel="noreferrer">Renato Gregio</a>. The ARI project provided the entire foundation that AzureScout builds upon — its ARM inventory module set, the draw.io diagram engine, Excel reporting, and more. AzureScout is now at 159 ARM + 17 Entra ID = 176 inventory modules — see <a href="./arm-modules.html">ARM Modules</a> and <a href="./entra-modules.html">Entra ID Modules</a>. We are deeply grateful for their work.</p><p>See <a href="./credits.html">Credits &amp; Attribution</a> for full details, or <a href="./ari-differences.html">Differences from ARI</a> for what has changed.</p></div>',89)])])}const m=t(n,[["render",d]]);export{p as __pageData,m as default};
